  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Expands water filling from the source up to the given distance using BFS.
   * Algorithm:
   *   1. If distance == 0, return.
   *   2. Perform BFS from source, following connected pipes in the direction they connect.
   *   3. Mark reachable pipes as filled up to the specified distance from source.
   *   4. Update filledTiles list with newly filled coordinates.
   *   5. Update prevFilledTiles count for loss detection.
   * Related Features: sourceCell, sinkCell, filledTiles, prevFilledTiles, prevFilledDistance fields
   * Related Classes: TerminationCell, Coordinate, Pipe, Direction
   * Input: distance : int - the maximum expansion distance from source (positive integer)
   * Output: void
   * Pre-condition: distance >= 0; source cell exists and is marked filled.
   * Post-condition: All pipes within the given distance from source that are connected are marked as filled. filledTiles list is updated.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    // If distance == 0, return.
    if (distance == 0) {
      return;
    }
    
    // Update prevFilledTiles count for loss detection.
    prevFilledTiles = getFilledTiles().size();
    prevFilledDistance = distance;
    
    // Perform BFS from source, following connected pipes in the direction they connect.
    Queue<Coordinate> queue = new LinkedList<Coordinate>();
    Queue<Integer> distQueue = new LinkedList<Integer>();
    
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    
    // Start BFS from source cell
    Coordinate sourceCoord = getSourceCell().getCoord();
    queue.add(sourceCoord);
    distQueue.add(0);
    
    while (!queue.isEmpty()) {
      Coordinate current = queue.poll();
      int currentDist = distQueue.poll();
      
      if (currentDist >= distance) {
        continue;
      }
      
      Cell currentCell = getCell()[current.getRow()][current.getCol()];
      
      // Determine outgoing directions from this cell
      EList<Direction> outDirections = new BasicEList<Direction>();
      
      if (currentCell instanceof FillableCell) {
        FillableCell fc = (FillableCell) currentCell;
        if (fc.getPipe() != null) {
          outDirections.addAll(fc.getPipe().getConnections());
        }
      } else if (currentCell instanceof TerminationCell) {
        TerminationCell tc = (TerminationCell) currentCell;
        // Source cell: water flows out in pointingTo direction
        // Sink cell: no outgoing connections (dead end)
        if (tc.getType() == TerminationType.SOURCE) {
          outDirections.add(tc.getPointingTo());
        }
      }
      
      for (Direction dir : outDirections) {
        Coordinate offset = helper.getOffset(dir);
        Coordinate neighborCoord = current.add(offset);
        
        int nr = neighborCoord.getRow();
        int nc = neighborCoord.getCol();
        
        // Check bounds
        if (nr < 0 || nr >= getRows() || nc < 0 || nc >= getCols()) {
          continue;
        }
        
        // Skip if already visited
        if (getFilledTiles().contains(neighborCoord)) {
          continue;
        }
        
        Cell neighborCell = getCell()[nr][nc];
        Direction oppositeDir = helper.getOpposite(dir);
        
        boolean connectsBack = false;
        if (neighborCell instanceof FillableCell) {
          FillableCell nfc = (FillableCell) neighborCell;
          if (nfc.getPipe() != null && nfc.getPipe().getConnections().contains(oppositeDir)) {
            connectsBack = true;
            nfc.getPipe().setFilled(true);
          }
        } else if (neighborCell instanceof TerminationCell) {
          TerminationCell ntc = (TerminationCell) neighborCell;
          // Water enters a termination cell if its pointingTo equals the direction we're coming from
          if (ntc.getPointingTo() == dir) {
            connectsBack = true;
            ntc.setFilled(true);
          }
        }
        
        if (connectsBack) {
          getFilledTiles().add(neighborCoord);
          queue.add(neighborCoord);
          distQueue.add(currentDist + 1);
        }
      }
    }
  }

